INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (3.414, "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", 62, 1, "2025/01/31 12:00:00", -416.5, "2030/01/01 14:59:59", 1, 1, 1000001, 190801, "カリン", 0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (3.099, "ミッションをクリアして、\n報酬をゲットしましょう！", 62, 1, "2025/01/31 12:00:00", -416.5, "2030/01/01 14:59:59", 2, 1, 1000002, 190801, "カリン", 0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (2.801, "受け取ることができる\n報酬があるようです\n確認してみてください", 63, 1, "2025/01/31 12:00:00", -416.5, "2030/01/01 14:59:59", 3, 1, 1000003, 190801, "カリン", 0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (0, "報酬がもらえますよ！\nチェックしてみてください", 63, 1, "2025/01/31 12:00:00", -416.5, "2030/01/01 14:59:59", 4, 2, 1000004, 190801, "カリン", 0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (2.12, "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", 64, 1, "2025/01/31 12:00:00", -363, "2030/01/01 14:59:59", 5, 2, 1000005, 190801, "カリン", 0, 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1.68, "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", 64, 1, "2025/01/31 12:00:00", -363, "2030/01/01 14:59:59", 6, 1, 1000006, 190801, "カリン", 0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (2.33, "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", 64, 1, "2025/01/31 12:00:00", -363, "2030/01/01 14:59:59", 7, 2, 1000007, 190801, "カリン", 0, 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (5.18, "今度の敵は、アタシにとっても\n放ってはおけない存在だ\n少年、アタシも全力で行くからさ\n一緒に守ろう、この世界を", 61, 10201, "2025/01/31 12:00:00", -285, "2030/01/01 14:59:59", 101, 3, 1020101, 133701, "ラビリスタ", -6, 7);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (8.77, "退屈の吹き飛ぶような\n戦いの気配がするなぁ坊や\nさっさとワタシをそこへ連れてゆけ\n世界も守ってやるさ、ついでにな", 61, 10201, "2025/01/31 12:00:00", -285, "2030/01/01 14:59:59", 201, 1, 1020102, 133901, "クリスティーナ", -2, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (15.5, "おや、私の力が必要……と？\nグレゴールが手伝うそうですよ\n私は戦わないのか、という顔ですね\n……考えておきます", 61, 10201, "2025/01/31 12:00:00", -285, "2030/01/01 14:59:59", 301, 6, 1020103, 133801, "ネネカ", 0, 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (9.061, "わたしだけの歌…\n一緒に、探してくれる…？\nあなたがいれば…\nもっとがんばれるから…", 61, 10202, "2025/02/28 12:00:00", -285, "2030/01/01 14:59:59", 101, 2, 1020201, 134301, "ランファ", 0, 5);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (7.699, "同じ唱喚士として、仲間として\n私にできることをします\n…これも、あなたが\n背中を押してくれたおかげですよ", 61, 10202, "2025/02/28 12:00:00", -285, "2030/01/01 14:59:59", 201, 1, 1020202, 134401, "チカ", 0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (8.595, "世界の平和が私とクローチェさんに\nかかってるんですよね？\nぼっちには過大すぎる期待ですけど\nふ、二人でなら背負ってみせます！", 61, 10203, "2025/03/31 12:00:00", -285, "2030/01/01 14:59:59", 101, 1, 1020301, 134601, "アオイ", 0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (7.758, "新しく手に入れたこの翼で…\nナイトさんがどこにいたって\nわたし、駆けつけちゃいますよっ！\nクローチェ・エアリアル発進ですっ", 61, 10203, "2025/03/31 12:00:00", -285, "2030/01/01 14:59:59", 201, 1, 1020302, 134501, "クローチェ", 0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (7, "今日はダーリンとの初デート♪\n二人でショッピングして、その後は\n…って私、指名手配されてる！？\nちょ、た…助けてダーリン～！！", 61, 10204, "2025/04/30 12:00:00", -285, "2030/01/01 14:59:59", 101, 2, 1020401, 132302, "ルイズマリー", 0, 6);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (7.904, "ルイちゃんのおばあちゃん優しくて\nいつもにこにこで、イロハ大好き♪\nでも一番好きなのは、角がすっごく\n大きくてかっこいいとこなんだ～♪", 61, 10204, "2025/04/30 12:00:00", -285, "2030/01/01 14:59:59", 201, 1, 1020402, 132402, "イロハ", 0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (8.487, "ノゾミちゃんのおかげで売上が安定\nしてきたのに、臨時休業、痛すぎる\n…ま、ルイちゃんのために\n一肌脱ぐか。行くよイロハ～", 61, 10204, "2025/04/30 12:00:00", -285, "2030/01/01 14:59:59", 301, 4, 1020403, 132502, "ソノ", 0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (8.763, "ヲ～ッホッホ♪\nあたくし様と同じお空気を吸える\nお幸運を噛みしめなさいですわ～♪\nヲ～ッホッホッホ～♪", 61, 10205, "2025/05/31 12:00:00", -285, "2030/01/01 14:59:59", 101, 1, 1020502, 134901, "カノン", 0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (6.417, "いきますよ騎士さん！\nカノンさんと力を合わせて…力を…\n…本当にあの人なんなんです？\nこれまでになく不安なんですけど！", 61, 10205, "2025/05/31 12:00:00", -285, "2030/01/01 14:59:59", 201, 1, 1020503, 134801, "ツムギ", 0, 3);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (10.335, "『願いが叶う海岸』か…怪しい\nだというのに、阿賀斗紫布菜たちは\n呑気に戯れている…見ていられない\n騎士クンは、わたしが守ってみせる", 61, 10206, "2025/06/30 12:00:00", -285, "2030/01/01 14:59:59", 101, 3, 1020601, 135001, "エリス", 0, 7);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (6.281, "せっかくの夏休みなんだし\nたまにはビーチでゆっくりしましょ\n…え、もしかしてこの夏もあんまり\n休めなかったりする感じなの？", 61, 10206, "2025/06/30 12:00:00", -285, "2030/01/01 14:59:59", 201, 2, 1020602, 135101, "シェフィ", 0, 4);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (12.244, "いっぱい。たべて\nおおきく。なると\nせーぎ。まもれる。はず\nお兄。いっしょに。スイカ。たべよ", 61, 10206, "2025/06/30 12:00:00", -285, "2030/01/01 14:59:59", 301, 1, 1020603, 135201, "プレシア", 0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (6.339, "ひと夏の冒険のはじまりです！\nアネモネさんも楽しんでくれたら\n…できれば、もう少し\n仲良くなれたらうれしいな…", 61, 10207, "2025/07/31 12:00:00", -285, "2030/01/01 14:59:59", 101, 2, 1020701, 135301, "クリア", 0, 8);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (8.184, "─幻の花…\n本当にあるのか謎─ですけど\n探すくらいは、\n付き合ってもいいです", 61, 10207, "2025/07/31 12:00:00", -285, "2030/01/01 14:59:59", 201, 7, 1020702, 135401, "アネモネ", 0, 9);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (3.906, "あははっ！　笑う門には福来る！\n笑ってればきっと、複製世界にも\n未来はやってくるって信じてる！\nそうだよね、シナツちゃん！", 61, 10208, "2025/08/31 12:00:00", -285, "2030/01/01 14:59:59", 101, 9, 1020801, 129101, "アイラ", 0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (14.465, "繰り返されるリセットの先の未来\n何度願っても手に入らなかった未来\n…でも、私は諦めない。絶対にだ\nキミも同じだろ…アイラ？", 61, 10208, "2025/08/31 12:00:00", -285, "2030/01/01 14:59:59", 201, 1, 1020802, 129201, "シナツ", 0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (8.662, "アイラの世界のみんなも、\n一生懸命生きてるんだ…！\n…なのに、世界の危機だなんて！\nあたし、絶対、絶対力になるよ！", 61, 10208, "2025/08/31 12:00:00", -285, "2030/01/01 14:59:59", 301, 4, 1020803, 100101, "ヒヨリ", 0, 3);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (10.915, "シナツ…もう一人の私\n彼女が大切にしている世界を\n絶対に終わらせはしない…！\n彼女と笑い合える未来のために！", 61, 10208, "2025/08/31 12:00:00", -285, "2030/01/01 14:59:59", 401, 1, 1020804, 100301, "レイ", 0, 3);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (6.042, "あ、ど、ども…\nあ、あんま見ねぇでくれっと\nその、恥ずかしくて…\n体が熱くなって、溶けちまう…", 61, 10209, "2025/09/30 12:00:00", -285, "2030/01/01 14:59:59", 101, 1, 1020901, 135802, "ユキノ", 0, 7);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (9.402, "なんで俺が幽霊に…意味不明だ\nこれじゃ死んでも死にきれねェ\n悪ィがこれも何かの縁だ、\nよろしく頼むぜ騎士公", 61, 10209, "2025/09/30 12:00:00", -285, "2030/01/01 14:59:59", 201, 4, 1020902, 135903, "サツキ", 0, 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (8.16, "う、うじゅる…\nサツキ姉しゃまを助けるためにも\nまずは、腹ごしらえでしゅね…！\nタコ焼き、召し上がってくだしゃい", 61, 10209, "2025/09/30 12:00:00", -285, "2030/01/01 14:59:59", 301, 8, 1020903, 136902, "ルルィ", 0, 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (5, "ひさしぶりのジオ・ゲヘナ\n歓迎パーティーで起きた殺人事件！\nランドソルの名探偵の名にかけて\n解き明かしてみせようじゃないか！", 61, 10210, "2025/10/31 12:00:00", -285, "2030/01/01 14:59:59", 101, 3, 1021001, 137401, "カスミ", 0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (8.12, "…わたしはどこの誰なのでしょう\nどこから来てどこへ行くのでしょう\nこの事件の真相が分かれば、\n何かが掴めるような気がいたします", 61, 10210, "2025/10/31 12:00:00", -285, "2030/01/01 14:59:59", 201, 4, 1021002, 136001, "アラクネ", 0, 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (6.386, "ナーナ、すいりとかろんぱとか、\nむずかしくてわかんないけど…\nお友だちとドーナツのためならっ\nせーいっぱいがんばるよっ！", 61, 10210, "2025/10/31 12:00:00", -285, "2030/01/01 14:59:59", 301, 4, 1021003, 136202, "ナーナ", 0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (7.438, "騎士クンに想いを伝えたい…だから\nミソラちゃん、わたしがんばるね！\n…あれ？　わたし、なんでこんなに\n必死になってるんだろう…？", 61, 10211, "2025/11/30 12:00:00", -285, "2030/01/01 14:59:59", 101, 3, 1021101, 136402, "ユイ", 0, 4);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (8.35, "騎士さんとのデートはわたしに\nお任せです★　なのでユイさんは\n安心して計画に専念して…たくさん\nドキドキしちゃってくださいね", 61, 10211, "2025/11/30 12:00:00", -285, "2030/01/01 14:59:59", 201, 1, 1021102, 136302, "ミソラ", 0, 5);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (5, "新しい年がやってくるね！\nお正月の料理も飾りつけも、\nお姉ちゃんにお任せだよ♪\nみんなで楽しく新年を迎えよう！", 61, 10212, "2025/12/31 12:00:00", -285, "2030/01/01 14:59:59", 101, 1, 1021201, 136501, "シズル", 0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (5.25, "おうちの掃除もトラブルも、 \n世界を揺るがす大ピンチも！\n今年のことは今年のうちに \nサッサと片付けちゃいますっ！", 61, 10212, "2025/12/31 12:00:00", -285, "2030/01/01 14:59:59", 201, 1, 1021202, 137902, "リノ", 0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (7.5, "年の瀬はギルドマスターも\nつい駆け回っちゃう忙しい時期だ！\n一年いろいろあったけど\nお互いイイ年を迎えよう、少年！", 61, 10212, "2025/12/31 12:00:00", -285, "2030/01/01 14:59:59", 301, 1, 1021203, 106801, "ラビリスタ", 0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (8.204, "漂う異国の料理の香り…それだけで\n世界中を旅した気分に浸れますね\nふふ、ほらクローチェ\nあまりはしゃぎすぎないように…♪", 61, 10213, "2026/01/31 12:00:00", -285, "2030/01/01 14:59:59", 101, 1, 1021301, 126501, "ライラエル", 0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (7.176, "異界の姫君と煮炊きにて競い合う…\n感奮興起、いとをかし\n華やかなる祭典と相成るよう、一肌\n脱がせていただきとう存じまする", 61, 10213, "2026/01/31 12:00:00", -285, "2030/01/01 14:59:59", 201, 1, 1021302, 129701, "ネフィ＝ネラ", 0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (8.602, "『ビストロプリンセス』のために\n料理の特訓を重ねてまいりました\nこの料理で騎士様の…い、いえ\n皆様の心とお腹を満たしますわ！", 61, 10213, "2026/01/31 12:00:00", -285, "2030/01/01 14:59:59", 301, 1, 1021303, 133101, "ヴァイオレット", 0, 5);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (10.14, "多様な味わいが織りなすハーモニー\nそれこそが我が国の矜持です\nもしもそれを乱すようであれば\nわたしも優しくはありませんよ？", 61, 10213, "2026/02/06 12:00:00", -285, "2030/01/01 14:59:59", 102, 1, 1021304, 138101, "ライラエル", 0, 3);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (10.152, "煉獄の穢土にてひと際輝く民草の心\n此れを守護りまするがわっちの責務\n如何な困難待ち受けようと\n不退転の矜持に揺らぎはありんせん", 61, 10213, "2026/02/06 12:00:00", -285, "2030/01/01 14:59:59", 202, 1, 1021305, 138201, "ネフィ＝ネラ", 0, 7);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (9.688, "裏世界の皆様は危機を脱し、\n残るはランドソルの皆様のみ…\n彼らを救い出すために、どうか…\nお立ち下さいペコリーヌ姫…！", 61, 10213, "2026/02/06 12:00:00", -285, "2030/01/01 14:59:59", 302, 4, 1021306, 138001, "ヴァイオレット", 0, 3);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (5.928, "みなさん、お待たせしちゃいました\nペコリーヌ、完全復活です☆\nみなさんの食卓を守るため\nもう二度と、わたしはめげません！", 61, 10213, "2026/02/12 12:00:00", -285, "2030/01/01 14:59:59", 401, 2, 1021307, 138301, "ペコリーヌ", 0, 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (9.19, "成行きで参加することになっちゃっ\nた尻相撲大会。ううっ、恥ずかしい\nけどやるしかないよね。…騎士さん\nいっぱい応援してくださいね？", 61, 10214, "2026/02/28 12:00:00", -285, "2030/01/01 14:59:59", 101, 4, 1021401, 138702, "ワカナ", 0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (8.724, "「お姉ちゃんを守れる自分になる」\nあの日の約束、今こそ果たしてみせ\nます。例えお姉ちゃんに背くことに\nなっても。例えそれが尻相撲でも！", 61, 10214, "2026/02/28 12:00:00", -285, "2030/01/01 14:59:59", 201, 1, 1021402, 138802, "シオリ", 0, 3);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (7.758, "私がへんたいふしんしゃさんって…\nただ生きているだけなのに、ひどい\n…まぁ死んでるんですけど…とか\n言ってる暇もない感じですか？", 61, 10215, "2026/03/31 12:00:00", -285, "2030/01/01 14:59:59", 101, 4, 1021501, 138902, "グレイス", 0, 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (6.375, "あの、助けてください！\n私がへんたいふしんしゃさんに\nなっちゃったみたいなんです…！\nどういう意味かは私もわかりません", 61, 10215, "2026/03/31 12:00:00", -285, "2030/01/01 14:59:59", 201, 6, 1021502, 139002, "キョウカ", 0, 4);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (6.173, "ましゃか、グレイス姉しゃまたちが\nへんたいふしんしゃさんだなんて…\n騎士しゃん。あたちたちも協力ちて\n二人の破滅エンドを回避ちましょう", 61, 10215, "2026/03/31 12:00:00", -285, "2030/01/01 14:59:59", 301, 6, 1021503, 136902, "ルルィ", 0, 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (4.202, "違う世界に来ちゃうし、\n驚きの連続だけど…\nわたしも精いっぱい頑張ります！\nアストルムのみんなと一緒に！", 61, 10216, "2026/04/30 12:00:00", -285, "2030/01/01 14:59:59", 101, 6, 1021601, 139202, "ミホ", 0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (2.842, "想定外の事象が発生したな…だが\nいかなる苦境も切り抜けてみせる\nいつもの自分とは違う姿になっても\nわたしはわたし、西住流だ", 61, 10216, "2026/04/30 12:00:00", -285, "2030/01/01 14:59:59", 201, 6, 1021602, 139302, "マホ", 0, 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (4.598, "何でこんなことになっているのか\n全然わからないけど、迷ってる暇は\nないわ。黒森峰の次期隊長として、\n前進あるのみ！　これも戦車道よ！", 61, 10216, "2026/04/30 12:00:00", -285, "2030/01/01 14:59:59", 301, 4, 1021603, 139402, "エリカ", 0, 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (6.533, "わたくしたちの悲願は、ロストさせ\nてしまった方々をお助けすること…\nそのためなら、どのような辛苦にも\n耐え抜いてみせます…！", 61, 10217, "2026/05/31 12:00:00", -285, "2030/01/01 14:59:59", 101, 4, 1021701, 125802, "リリ", 0, 3);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (5, "みんなも。せーぎも。\nクリアも。パパ、も。\nぜったい、たすける。\nみててね。お兄。", 61, 10217, "2026/05/31 12:00:00", -285, "2030/01/01 14:59:59", 301, 3, 1021702, 126102, "プレシア", 0, 3);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (5.214, "癒しの力を使うこと…\nもう、ためらいません！\nモネちゃんやお兄さん…\nみんなに許してもらうためにも！", 61, 10217, "2026/05/31 12:00:00", -285, "2030/01/01 14:59:59", 201, 3, 1021703, 126002, "クリア", 0, 4);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (8.781, "ヴァルキュリア─皆様を助けたい\nという願いを、力にできるのなら…\nわたくしたちは、きっと誰にも\n負けません！　一意専心です…！", 61, 10217, "2026/05/31 12:00:00", -285, "2030/01/01 14:59:59", 102, 1, 1021704, 139501, "リリ", 0, 3);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (6.529, "このヴァルキュリアって職業、\nまるで天使みたいな格好ですよね\nうーん…『聖女』ちゃんって\n呼ばれるよりは、マシかな？", 61, 10217, "2026/05/31 12:00:00", -285, "2030/01/01 14:59:59", 202, 2, 1021705, 139601, "クリア", 0, 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (3.195, "ばるきり。もーど。\nはね。まっしろ。\nはっぴーちゃんと。おなじ。\nいいかんじ。", 61, 10217, "2026/05/31 12:00:00", -285, "2030/01/01 14:59:59", 302, 3, 1021706, 139701, "プレシア", 0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (12.43, "ダーリンと一緒に南の島で\nリゾート開発なんて夢みたい♪\nああ…幸せ、最高の夏だわ…\n触れたら爆発さえしなければ～…っ", 61, 10218, "2026/06/30 12:00:00", -285, "2030/01/01 14:59:59", 101, 2, 1021801, 139902, "ルイズマリー", 0, 3);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (6.35, "青い空、白い雲…無人島リゾートで\n大儲けですわ～♪　こらこらそこ、\nイチャついてるんじゃないですのよ\n触れたらドカンですわよ、ドカン！", 61, 10218, "2026/06/30 12:00:00", -285, "2030/01/01 14:59:59", 201, 2, 1021802, 140001, "クレジッタ", 0, 3);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (10.23, "みんなはかわいいぼくを見られて、\nぼくはみんなからラヴをもらう♡\n最高のウィンウィンだよね、これ♡\nで、最後はお兄さんをドレーに…♡", 61, 10219, "2026/07/31 12:00:00", -285, "2030/01/01 14:59:59", 101, 1, 1021901, 140102, "フブキ", 0, 5);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (5.584, "けんぞくとたくさん遊ぶためにも、\nみんなからラヴをもらわなくちゃ♪\nバズっちゃおー作戦、\n一緒に考えてね！　けんぞくぅ♪", 61, 10219, "2026/07/31 12:00:00", -285, "2030/01/01 14:59:59", 201, 1, 1021902, 140201, "ヴァンピィ", 0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (2.8, "あっちもこっちも、\nエマージェンシーですっ！\nみんなのピンチを助けるために\n行きましょうっ、ナイトさんっ！", 61, 10220, "2026/08/31 12:00:00", -285, "2030/01/01 14:59:59", 201, 6, 1022001, 126401, "クローチェ", 0, 3);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (8.9, "みんながあたしを許してくれても…\nあたしは、あたしを許せない\nそれでも…この世界が危ないなら\n迷ってなんか、いられない", 61, 10220, "2026/08/31 12:00:00", -285, "2030/01/01 14:59:59", 101, 4, 1022002, 127802, "ヴルム", 0, 3);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (4.49, "クローチェ、サブマリンモードっ\n換装完了ですっ♪\nどんな荒波も、ナイトさんとなら\n越えちゃいますからっ！", 61, 10220, "2026/08/31 12:00:00", -285, "2030/01/01 14:59:59", 202, 2, 1022003, 140602, "クローチェ", 0, 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (9.42, "偽物でも、創り物でもいい\nあたしの中にある気持ちは、\nあたしの本物だから\n今度こそ、この力で守ってみせる", 61, 10220, "2026/08/31 12:00:00", -285, "2030/01/01 14:59:59", 102, 1, 1022004, 140501, "ヴルム", 0, 3);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (7, "世界と向き合うなんてこと…\n私には、わからない\nそれでも、受けた借りは\nちゃんと返さないとね", 61, 10220, "2026/08/31 12:00:00", -285, "2030/01/01 14:59:59", 301, 4, 1022005, 140402, "リーザ", 0, 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (8.61, "ゲームの世界、ね\n分からないことばかりだけれど\nやることは変わらないわ\nどんな場所でもわたしは負けない！", 61, 10221, "2026/10/31 12:00:00", -285, "2030/01/01 14:59:59", 101, 1, 1022101, 141101, "アーモンドアイ", 0, 3);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (3.55, "ゴルシさんは相変わらずやねぇ…\nまぁせっかくの異世界やし\nいつもと違うレース、\n楽しませてもらいましょ", 61, 10221, "2026/10/31 12:00:00", -285, "2030/01/01 14:59:59", 201, 6, 1022102, 141201, "ラッキーライラック", 0, 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (8.26, "なんて美しい世界でしょう…！\n現実では見られない景色ばかり\nぜひ一度、この世界の大自然を\n隅から隅まで駆け抜けてみたいです", 61, 10221, "2026/10/31 12:00:00", -285, "2030/01/01 14:59:59", 301, 2, 1022103, 141301, "デアリングタクト", 0, 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (8.79, "来ったぞ～来ったぞ～\nアストルム～っと！\nな～んか平和そうな世界だな\nちょっくら盛り上げてくっか！", 61, 10221, "2026/10/31 12:00:00", -285, "2030/01/01 14:59:59", 401, 2, 1022104, 141001, "ゴールドシップ", 0, 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (8.61, "ゲームの世界、ね\n分からないことばかりだけれど\nやることは変わらないわ\nどんな場所でもわたしは負けない！", 61, 10221, "2026/10/31 12:00:00", -285, "2030/01/01 14:59:59", 101, 1, 1022105, 141101, "アーモンドアイ", 0, 3);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (2.69, "（剣と魔法！　ええなぁ～！\nうちも魔法覚えられるやろか\nレースの後に花咲かせたり…\nくぅ～っ！　はよ試したいわ！）", 61, 10221, "2026/10/31 12:00:00", -285, "2030/01/01 14:59:59", 202, 1, 1022106, 141201, "ラッキーライラック", 0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (8.26, "なんて美しい世界でしょう…！\n現実では見られない景色ばかり\nぜひ一度、この世界の大自然を\n隅から隅まで駆け抜けてみたいです", 61, 10221, "2026/10/31 12:00:00", -285, "2030/01/01 14:59:59", 301, 2, 1022107, 141301, "デアリングタクト", 0, 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (8.79, "来ったぞ～来ったぞ～\nアストルム～っと！\nな～んか平和そうな世界だな\nちょっくら盛り上げてくっか！", 61, 10221, "2026/10/31 12:00:00", -285, "2030/01/01 14:59:59", 401, 2, 1022108, 141001, "ゴールドシップ", 0, 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (3.414, "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", 62, 2, "2026/04/10 12:00:00", -416.5, "2030/01/01 14:59:59", 1, 1, 2000001, 190805, "カリン", 0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (3.099, "ミッションをクリアして、\n報酬をゲットしましょう！", 62, 2, "2026/04/10 12:00:00", -416.5, "2030/01/01 14:59:59", 2, 1, 2000002, 190805, "カリン", 0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (2.801, "受け取ることができる\n報酬があるようです\n確認してみてください", 63, 2, "2026/04/10 12:00:00", -416.5, "2030/01/01 14:59:59", 3, 1, 2000003, 190805, "カリン", 0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (0, "報酬がもらえますよ！\nチェックしてみてください", 63, 2, "2026/04/10 12:00:00", -416.5, "2030/01/01 14:59:59", 4, 2, 2000004, 190805, "カリン", 0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (2.12, "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", 64, 2, "2026/04/10 12:00:00", -363, "2030/01/01 14:59:59", 5, 2, 2000005, 190805, "カリン", 0, 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1.68, "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", 64, 2, "2026/04/10 12:00:00", -363, "2030/01/01 14:59:59", 6, 1, 2000006, 190805, "カリン", 0, 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (2.33, "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", 64, 2, "2026/04/10 12:00:00", -363, "2030/01/01 14:59:59", 7, 2, 2000007, 190805, "カリン", 0, 1);
